-- 0001_initial: the game store, translated from the SQLite schema in
-- src/thugsak/store.py (SCHEMA + MIGRATIONS + POST_MIGRATION_INDEXES).
--
-- Deliberate choices:
--   * Timestamps stay TEXT (ISO-8601 UTC strings), exactly as in SQLite. The
--     as-of guard compares them as strings and every caller writes them that
--     way; changing the type is a separate, testable change, not a port.
--   * REAL -> DOUBLE PRECISION. Postgres REAL is 4-byte float4 and would
--     quietly round calibration constants and prices.
--   * AUTOINCREMENT -> GENERATED BY DEFAULT AS IDENTITY (BY DEFAULT so the
--     data copy in phase 4 can insert the existing ids, then reset).
--   * Row-level security is ENABLED on every table with NO policies. Supabase
--     publishes every table in `public` through its HTTP API; with RLS on and
--     no policy, that API can read and write nothing. The app connects as the
--     database owner, which bypasses RLS, so it is unaffected.

CREATE TABLE IF NOT EXISTS teams (
    team_id      TEXT PRIMARY KEY,
    league       TEXT NOT NULL,
    canonical    TEXT NOT NULL,
    display_name TEXT,
    espn_id      TEXT,
    is_d1        INTEGER,
    UNIQUE (league, canonical)
);

CREATE TABLE IF NOT EXISTS team_aliases (
    league  TEXT NOT NULL,
    alias   TEXT NOT NULL,
    source  TEXT NOT NULL,
    team_id TEXT NOT NULL REFERENCES teams(team_id),
    PRIMARY KEY (league, alias, source)
);
-- Foreign-key column index: Postgres does not create one automatically.
CREATE INDEX IF NOT EXISTS ix_aliases_team ON team_aliases(team_id);

CREATE TABLE IF NOT EXISTS games (
    game_id       TEXT PRIMARY KEY,
    league        TEXT NOT NULL,
    season        INTEGER NOT NULL,
    season_type   TEXT DEFAULT 'regular',
    start_time    TEXT NOT NULL,
    home_team     TEXT NOT NULL,
    away_team     TEXT NOT NULL,
    home_score    INTEGER,
    away_score    INTEGER,
    completed     INTEGER NOT NULL DEFAULT 0,
    neutral_site  INTEGER NOT NULL DEFAULT 0,
    close_spread  DOUBLE PRECISION,
    close_total   DOUBLE PRECISION,
    close_home_ml INTEGER,
    close_away_ml INTEGER,
    source        TEXT,
    slate_date    TEXT
);
CREATE INDEX IF NOT EXISTS ix_games_league_time ON games(league, start_time);
CREATE INDEX IF NOT EXISTS ix_games_season ON games(league, season);
CREATE INDEX IF NOT EXISTS ix_games_teams ON games(league, home_team, away_team);
CREATE INDEX IF NOT EXISTS ix_games_slate ON games(league, slate_date);

CREATE TABLE IF NOT EXISTS team_game_stats (
    game_id        TEXT NOT NULL REFERENCES games(game_id) ON DELETE CASCADE,
    team_id        TEXT NOT NULL,
    opponent_id    TEXT NOT NULL,
    league         TEXT NOT NULL,
    season         INTEGER NOT NULL,
    start_time     TEXT NOT NULL,
    is_home        INTEGER NOT NULL,
    neutral_site   INTEGER NOT NULL DEFAULT 0,
    points_for     INTEGER,
    points_against INTEGER,
    detail         TEXT,
    PRIMARY KEY (game_id, team_id)
);
CREATE INDEX IF NOT EXISTS ix_tgs_team_time ON team_game_stats(team_id, start_time);
CREATE INDEX IF NOT EXISTS ix_tgs_league_time ON team_game_stats(league, start_time);

CREATE TABLE IF NOT EXISTS ratings_pit (
    league   TEXT NOT NULL,
    as_of    TEXT NOT NULL,
    team_id  TEXT NOT NULL,
    rating   DOUBLE PRECISION NOT NULL,
    n_games  INTEGER NOT NULL,
    PRIMARY KEY (league, as_of, team_id)
);

CREATE TABLE IF NOT EXISTS calibration (
    league     TEXT NOT NULL,
    key        TEXT NOT NULL,
    value      DOUBLE PRECISION NOT NULL,
    n_games    INTEGER,
    seasons    TEXT,
    fitted_at  TEXT NOT NULL,
    PRIMARY KEY (league, key)
);

CREATE TABLE IF NOT EXISTS predictions (
    pred_id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    game_id          TEXT NOT NULL,
    league           TEXT NOT NULL,
    as_of            TEXT NOT NULL,
    created_at       TEXT NOT NULL,
    pred_home_points DOUBLE PRECISION,
    pred_away_points DOUBLE PRECISION,
    pred_spread      DOUBLE PRECISION,
    pred_total       DOUBLE PRECISION,
    model_version    TEXT,
    payload          TEXT,
    matchup          TEXT,
    slate_date       TEXT,
    home_team        TEXT,
    away_team        TEXT,
    actual_home      INTEGER,
    actual_away      INTEGER,
    settled_at       TEXT,
    bets             TEXT,
    the_call         TEXT,
    kalshi_money_usd DOUBLE PRECISION
);
CREATE INDEX IF NOT EXISTS ix_pred_game ON predictions(game_id);
CREATE INDEX IF NOT EXISTS ix_pred_settled ON predictions(league, settled_at);

CREATE TABLE IF NOT EXISTS meta (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS players (
    athlete_id TEXT PRIMARY KEY,
    league     TEXT NOT NULL,
    team_id    TEXT NOT NULL,
    name       TEXT,
    position   TEXT,
    source     TEXT,
    updated_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_players_team ON players(league, team_id);

CREATE TABLE IF NOT EXISTS player_games (
    athlete_id  TEXT NOT NULL,
    event_id    TEXT NOT NULL,
    league      TEXT NOT NULL,
    team_id     TEXT NOT NULL,
    date        TEXT NOT NULL,
    opponent    TEXT,
    home_away   TEXT,
    result      TEXT,
    stats       TEXT,
    source      TEXT,
    fetched_at  TEXT NOT NULL,
    PRIMARY KEY (athlete_id, event_id)
);
CREATE INDEX IF NOT EXISTS ix_pg_team_date ON player_games(league, team_id, date);

CREATE TABLE IF NOT EXISTS depth_chart (
    league     TEXT NOT NULL,
    team_id    TEXT NOT NULL,
    position   TEXT NOT NULL,
    athlete_id TEXT NOT NULL,
    rank       INTEGER NOT NULL,
    as_of      TEXT NOT NULL,
    PRIMARY KEY (league, team_id, position, rank, as_of)
);
CREATE INDEX IF NOT EXISTS ix_depth_team ON depth_chart(league, team_id, as_of);

CREATE TABLE IF NOT EXISTS injury_snapshots (
    snapshot_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    league      TEXT NOT NULL,
    team_id     TEXT NOT NULL,
    athlete_id  TEXT NOT NULL,
    name        TEXT,
    position    TEXT,
    status      TEXT NOT NULL,
    detail      TEXT,
    as_of       TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS ix_inj_league_asof ON injury_snapshots(league, as_of);
CREATE INDEX IF NOT EXISTS ix_inj_athlete ON injury_snapshots(athlete_id, as_of);

CREATE TABLE IF NOT EXISTS agent_runs (
    run_id      BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    agent       TEXT NOT NULL,
    league      TEXT,
    started_at  TEXT NOT NULL,
    finished_at TEXT,
    status      TEXT NOT NULL,
    signature   TEXT,
    summary     TEXT,
    writes      TEXT,
    error       TEXT
);
CREATE INDEX IF NOT EXISTS ix_runs_agent ON agent_runs(agent, started_at);
CREATE INDEX IF NOT EXISTS ix_runs_agent_league ON agent_runs(agent, league, started_at);

-- Lock the Supabase HTTP API out of every table (see header).
ALTER TABLE teams            ENABLE ROW LEVEL SECURITY;
ALTER TABLE team_aliases     ENABLE ROW LEVEL SECURITY;
ALTER TABLE games            ENABLE ROW LEVEL SECURITY;
ALTER TABLE team_game_stats  ENABLE ROW LEVEL SECURITY;
ALTER TABLE ratings_pit      ENABLE ROW LEVEL SECURITY;
ALTER TABLE calibration      ENABLE ROW LEVEL SECURITY;
ALTER TABLE predictions      ENABLE ROW LEVEL SECURITY;
ALTER TABLE meta             ENABLE ROW LEVEL SECURITY;
ALTER TABLE players          ENABLE ROW LEVEL SECURITY;
ALTER TABLE player_games     ENABLE ROW LEVEL SECURITY;
ALTER TABLE depth_chart      ENABLE ROW LEVEL SECURITY;
ALTER TABLE injury_snapshots ENABLE ROW LEVEL SECURITY;
ALTER TABLE agent_runs       ENABLE ROW LEVEL SECURITY;
